  // Карточка дня: {title, body} или null. skip — номера спрятанных шагов рычага (fit → skip).
  function card(lever, day, lang, skip){
    var arr = C[lever]; if (!arr || !day) return null;
    var i = Math.max(1, Math.min(7, day)) - 1, c = arr[i];
    var alt = (ALT[lever] || []).filter(function(a){ return a.d === i + 1 && Array.isArray(skip) && skip.indexOf(a.step) >= 0; })[0];
    if (alt) c = alt;
    var tx = function(o){ return (o && (o[lang] || o.en || o.ru)) || ''; };
    return c ? { title: tx(c.t), body: tx(c.b) } : null;
  }
  window.vialCourses = { card: card, levers: function(){ return Object.keys(C); } };
